import { DynamoDBClient, GetItemCommand, PutItemCommand } from '@aws-sdk/client-dynamodb';
import {
  CognitoIdentityProviderClient,
  CreateGroupCommand,
  DeleteGroupCommand,
  DescribeUserPoolCommand,
  ListUsersInGroupCommand,
  UpdateUserPoolCommand,
} from '@aws-sdk/client-cognito-identity-provider';
import { validateTenantAccess, getTenantIdFromRequest, createResponse, createLogger, logRequest } from 'admin-auth';

const logger = createLogger('settings');

const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });
const cognito = new CognitoIdentityProviderClient({ region: process.env.AWS_REGION });

// Fields from amfaConfigs that we expose in the settings UI
const AMFA_CONFIG_UI_FIELDS = [
  'enable_password_reset',
  'enable_self_service',
  'enable_self_service_remove_buttons',
  'enable_user_registration',
  'enable_have_i_been_pwned',
  'enable_google_recaptcha',
  'recaptcha_mode',
  'recaptcha_key',
  'recaptcha_secret',
  'recaptcha_api_key',
  'recaptcha_project_id',
  'master_additional_otp_methods',
  'user_registration_default_group',
  'update_profile_force_mobile_token_first_if_registered',
  'enable_password_expire',
  'passwords_expire_days',
  'enable_prevent_password_reuse',
  'prevent_password_reuse_count',
  'enable_auto_pwd_reset_on_threat',
  'allowed_domains',
];

// Secret-bearing settings: never echoed; the response carries `<field>_configured`
// booleans instead, and a PUT that omits them (or sends '') keeps the stored value.
const SECRET_FIELDS = ['recaptcha_secret', 'recaptcha_api_key'];

// Fields from amfaLegals
// NOTE: Legal URLs are now managed via the /brandings/{tenantId}_amfa API.
const LEGAL_FIELDS = [];

// Fields from amfaBrandings (Login Service branding)
// NOTE: Login Service Branding is now managed via the /brandings/{tenantId}_amfa API.
// These fields are kept here only for backward compatibility with existing settings
// that may have been saved through the old settings UI.
const BRANDING_FIELDS = [];

/** Special policy groups (contain '-') cannot be deleted */
const isSpecialPolicyGroup = (groupName) => groupName.includes('-');

const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const MAX_POLICIES = 50;
const POLICY_NAME_RE = /^[A-Za-z0-9_-]{1,128}$/;

/**
 * Every policy key becomes a Cognito group (one CreateGroup each) and the
 * object is stored verbatim for the login service, so bound it before any
 * call. Returns an error string naming the field, or null.
 */
const validatePolicies = (policies) => {
  if (!isPlainObject(policies)) return 'policies must be an object';
  const keys = Object.keys(policies);
  if (keys.length > MAX_POLICIES) return `policies: at most ${MAX_POLICIES} groups allowed`;
  for (const key of keys) {
    if (!POLICY_NAME_RE.test(key)) return `policies: invalid group name "${key.slice(0, 128)}"`;
    if (!isPlainObject(policies[key])) return `policies.${key} must be an object`;
  }
  return null;
};

// ---------------------------------------------------------------------------
// Cognito password policy (user-pool level, applies to every user of the tenant)
// ---------------------------------------------------------------------------

/** Cognito limits: MinimumLength 6-99, TemporaryPasswordValidityDays 0-365 */
const PASSWORD_POLICY_LIMITS = {
  minimum_length: { min: 6, max: 99 },
  temporary_password_validity_days: { min: 0, max: 365 },
};
const PASSWORD_POLICY_FLAGS = ['require_uppercase', 'require_lowercase', 'require_numbers', 'require_symbols'];

/** Cognito PasswordPolicy -> UI shape (snake_case, no PasswordHistorySize: AMFA has its own reuse setting) */
const toUiPasswordPolicy = (p = {}) => ({
  minimum_length: p.MinimumLength ?? 8,
  require_uppercase: p.RequireUppercase ?? false,
  require_lowercase: p.RequireLowercase ?? false,
  require_numbers: p.RequireNumbers ?? false,
  require_symbols: p.RequireSymbols ?? false,
  temporary_password_validity_days: p.TemporaryPasswordValidityDays ?? 7,
});

/**
 * Validate the UI shape and convert it to a Cognito PasswordPolicy.
 * Returns { policy } or { error } (string, safe to return as 400).
 */
const toCognitoPasswordPolicy = (ui) => {
  if (!ui || typeof ui !== 'object') return { error: 'password_policy must be an object' };

  const ints = {};
  for (const [field, { min, max }] of Object.entries(PASSWORD_POLICY_LIMITS)) {
    const n = Number(ui[field]);
    if (!Number.isInteger(n) || n < min || n > max) {
      return { error: `password_policy.${field} must be an integer between ${min} and ${max}` };
    }
    ints[field] = n;
  }
  for (const flag of PASSWORD_POLICY_FLAGS) {
    if (typeof ui[flag] !== 'boolean') {
      return { error: `password_policy.${flag} must be true or false` };
    }
  }

  return {
    policy: {
      MinimumLength: ints.minimum_length,
      RequireUppercase: ui.require_uppercase,
      RequireLowercase: ui.require_lowercase,
      RequireNumbers: ui.require_numbers,
      RequireSymbols: ui.require_symbols,
      TemporaryPasswordValidityDays: ints.temporary_password_validity_days,
    },
  };
};

const fetchUserPool = async (userPoolId) => {
  const res = await cognito.send(new DescribeUserPoolCommand({ UserPoolId: userPoolId }));
  return res.UserPool;
};

/**
 * Replace only Policies.PasswordPolicy on the pool.
 * UpdateUserPool resets every attribute it is not given to its default, so
 * all other updatable attributes are copied back from DescribeUserPool
 * (same approach as provision-tenant/cognito-provisioning.mjs).
 */
const updatePasswordPolicy = async (pool, passwordPolicy) => {
  // UnusedAccountValidityDays is the deprecated twin of TemporaryPasswordValidityDays;
  // Cognito rejects a request that carries both, so drop it.
  const { UnusedAccountValidityDays, ...adminCreateUserConfig } = pool.AdminCreateUserConfig || {};

  const preserved = {
    DeletionProtection: pool.DeletionProtection,
    LambdaConfig: pool.LambdaConfig,
    AutoVerifiedAttributes: pool.AutoVerifiedAttributes,
    SmsVerificationMessage: pool.SmsVerificationMessage,
    EmailVerificationMessage: pool.EmailVerificationMessage,
    EmailVerificationSubject: pool.EmailVerificationSubject,
    VerificationMessageTemplate: pool.VerificationMessageTemplate,
    SmsAuthenticationMessage: pool.SmsAuthenticationMessage,
    UserAttributeUpdateSettings: pool.UserAttributeUpdateSettings,
    MfaConfiguration: pool.MfaConfiguration,
    DeviceConfiguration: pool.DeviceConfiguration,
    EmailConfiguration: pool.EmailConfiguration,
    SmsConfiguration: pool.SmsConfiguration,
    UserPoolTags: pool.UserPoolTags,
    AdminCreateUserConfig: pool.AdminCreateUserConfig ? adminCreateUserConfig : undefined,
    UserPoolAddOns: pool.UserPoolAddOns,
    AccountRecoverySetting: pool.AccountRecoverySetting,
    UserPoolTier: pool.UserPoolTier,
  };
  // Drop undefined keys so the SDK does not serialise them
  Object.keys(preserved).forEach(k => preserved[k] === undefined && delete preserved[k]);

  await cognito.send(new UpdateUserPoolCommand({
    UserPoolId: pool.Id,
    ...preserved,
    Policies: { ...(pool.Policies || {}), PasswordPolicy: passwordPolicy },
  }));
};

const samePasswordPolicy = (a, b) =>
  Object.keys(a).every(k => a[k] === b?.[k]);

const fetchConfig = async (configType, tenantId) => {
  const params = {
    TableName: process.env.AMFACONFIG_TABLE,
    Key: {
      id: { S: tenantId },
      configtype: { S: configType },
    },
  };
  const result = await dynamodb.send(new GetItemCommand(params));
  if (result.Item?.value?.S) {
    return JSON.parse(result.Item.value.S);
  }
  return null;
};

const saveConfig = async (configType, tenantId, value) => {
  const params = {
    TableName: process.env.AMFACONFIG_TABLE,
    Item: {
      id: { S: tenantId },
      configtype: { S: configType },
      value: { S: JSON.stringify(value) },
    },
  };
  await dynamodb.send(new PutItemCommand(params));
};

/**
 * Bump the configVersion record for a tenant.
 * This signals the service-side configCache to invalidate its in-memory cache
 * so that config changes propagate within ~10 seconds instead of waiting 5 minutes.
 */
const bumpConfigVersion = async (tenantId) => {
  try {
    const params = {
      TableName: process.env.AMFACONFIG_TABLE,
      Item: {
        id: { S: tenantId },
        configtype: { S: 'configVersion' },
        value: { S: JSON.stringify({ version: Date.now().toString(), updatedAt: new Date().toISOString() }) },
      },
    };
    await dynamodb.send(new PutItemCommand(params));
    logger.info(`Config version bumped for tenant ${tenantId}`);
  } catch (err) {
    // Non-blocking: version bump failure should not break the settings save
    logger.warn(`Failed to bump config version for tenant ${tenantId}:`, err.message);
  }
};

/**
 * Build response from all config types
 */
const buildSettingsResponse = (amfaConfigs, amfaLegals, amfaBrandings) => {
  const settings = {};

  if (amfaConfigs) {
    AMFA_CONFIG_UI_FIELDS.forEach(field => {
      if (SECRET_FIELDS.includes(field)) {
        settings[`${field}_configured`] = Boolean(amfaConfigs[field]);
      } else if (amfaConfigs[field] !== undefined) {
        settings[field] = amfaConfigs[field];
      }
    });
  }

  if (amfaLegals) {
    LEGAL_FIELDS.forEach(field => {
      if (amfaLegals[field] !== undefined) {
        settings[field] = amfaLegals[field];
      }
    });
  }

  if (amfaBrandings) {
    BRANDING_FIELDS.forEach(field => {
      if (amfaBrandings[field] !== undefined) {
        settings[field] = amfaBrandings[field];
      }
    });
  }

  return settings;
};

/**
 * Apply UI settings back to config objects, preserving non-UI fields
 */
const applySettingsToConfigs = (settings, existingAmfaConfigs, existingAmfaLegals, existingAmfaBrandings) => {
  const updatedAmfaConfigs = { ...(existingAmfaConfigs || {}) };
  AMFA_CONFIG_UI_FIELDS.forEach(field => {
    if (SECRET_FIELDS.includes(field) && !settings[field]) return; // keep the stored secret
    if (settings[field] !== undefined) {
      updatedAmfaConfigs[field] = settings[field];
    }
  });

  const updatedAmfaLegals = { ...(existingAmfaLegals || {}) };
  LEGAL_FIELDS.forEach(field => {
    if (settings[field] !== undefined) {
      updatedAmfaLegals[field] = settings[field];
    }
  });

  const updatedAmfaBrandings = { ...(existingAmfaBrandings || {}) };
  BRANDING_FIELDS.forEach(field => {
    if (settings[field] !== undefined) {
      updatedAmfaBrandings[field] = settings[field];
    }
  });

  return { updatedAmfaConfigs, updatedAmfaLegals, updatedAmfaBrandings };
};

/**
 * Sync Cognito user groups with policy changes.
 * - New normal policy groups → CreateGroup
 * - Deleted normal policy groups → DeleteGroup (only if empty)
 * Special policy groups (containing '-') are never synced with Cognito.
 */
const syncCognitoGroups = async (oldPolicies, newPolicies, userPoolId) => {
  const oldNormalGroups = Object.keys(oldPolicies || {}).filter(g => !isSpecialPolicyGroup(g));
  const newNormalGroups = Object.keys(newPolicies || {}).filter(g => !isSpecialPolicyGroup(g));

  const added = newNormalGroups.filter(g => !oldNormalGroups.includes(g));
  const removed = oldNormalGroups.filter(g => !newNormalGroups.includes(g));

  const results = { created: [], deleted: [], errors: [] };

  // Create new groups
  for (const groupName of added) {
    try {
      await cognito.send(new CreateGroupCommand({
        UserPoolId: userPoolId,
        GroupName: groupName,
        Description: `Policy group (rank: ${newPolicies[groupName]?.rank || 'N/A'})`,
      }));
      results.created.push(groupName);
      logger.info(`Created Cognito group: ${groupName}`);
    } catch (err) {
      if (err.name === 'GroupExistsException') {
        logger.info(`Cognito group already exists: ${groupName}`);
      } else {
        logger.error(`Failed to create group ${groupName}:`, err.message);
        results.errors.push({ group: groupName, action: 'create', error: err.message });
      }
    }
  }

  // Delete removed groups (only if no users in them)
  for (const groupName of removed) {
    try {
      // Check if group has users
      const usersInGroup = await cognito.send(new ListUsersInGroupCommand({
        UserPoolId: userPoolId,
        GroupName: groupName,
        Limit: 1,
      }));

      if (usersInGroup.Users && usersInGroup.Users.length > 0) {
        logger.warn(`Cannot delete group ${groupName}: has users`);
        results.errors.push({
          group: groupName,
          action: 'delete',
          error: 'Group has users. Remove users from group first.',
        });
        continue;
      }

      await cognito.send(new DeleteGroupCommand({
        UserPoolId: userPoolId,
        GroupName: groupName,
      }));
      results.deleted.push(groupName);
      logger.info(`Deleted Cognito group: ${groupName}`);
    } catch (err) {
      if (err.name === 'ResourceNotFoundException') {
        logger.info(`Cognito group not found (already deleted): ${groupName}`);
      } else {
        logger.error(`Failed to delete group ${groupName}:`, err.message);
        results.errors.push({ group: groupName, action: 'delete', error: err.message });
      }
    }
  }

  return results;
};

export const handler = async (event) => {
  logRequest(logger, event);

  const tenantId = getTenantIdFromRequest(event) || event.pathParameters?.id;

  if (!tenantId) {
    return createResponse(400, { error: 'tenant_id required in request' });
  }

  const authResult = await validateTenantAccess(event, tenantId);
  if (!authResult.authorized) {
    return createResponse(authResult.statusCode, { error: authResult.error });
  }

  const { userPoolId } = authResult;
  logger.info(`Authorized access for tenant ${tenantId}`);

  const httpMethod = event.requestContext?.http?.method || event.httpMethod || 'GET';

  try {
    if (httpMethod === 'GET') {
      const [amfaConfigs, amfaLegals, amfaBrandings, amfaPolicies, pool] = await Promise.all([
        fetchConfig('amfaConfigs', tenantId),
        fetchConfig('amfaLegals', tenantId),
        fetchConfig('amfaBrandings', tenantId),
        fetchConfig('amfaPolicies', tenantId),
        // Non-blocking: the rest of the settings page must still load if Cognito is unreachable
        fetchUserPool(userPoolId).catch(err => {
          logger.warn(`DescribeUserPool failed for tenant ${tenantId}:`, err.message);
          return null;
        }),
      ]);

      const settings = buildSettingsResponse(amfaConfigs, amfaLegals, amfaBrandings);
      return createResponse(200, {
        data: {
          ...settings,
          policies: amfaPolicies || {},
          ...(pool && { password_policy: toUiPasswordPolicy(pool.Policies?.PasswordPolicy) }),
        },
      });

    } else if (httpMethod === 'PUT') {
      const body = typeof event.body === 'string' ? JSON.parse(event.body) : event.body;
      const incomingSettings = body.data;

      if (!incomingSettings) {
        return createResponse(400, { error: 'Missing data in request body' });
      }

      // Validate the Cognito password policy before touching anything
      let cognitoPasswordPolicy = null;
      if (incomingSettings.password_policy !== undefined) {
        const { policy, error } = toCognitoPasswordPolicy(incomingSettings.password_policy);
        if (error) {
          return createResponse(400, { error });
        }
        cognitoPasswordPolicy = policy;
      }
      // Validate policies before anything is read or written (D7)
      if (incomingSettings.policies !== undefined) {
        const policiesError = validatePolicies(incomingSettings.policies);
        if (policiesError) {
          return createResponse(400, { error: policiesError });
        }
      }

      const [existingAmfaConfigs, existingAmfaLegals, existingAmfaBrandings, existingPolicies] = await Promise.all([
        fetchConfig('amfaConfigs', tenantId),
        fetchConfig('amfaLegals', tenantId),
        fetchConfig('amfaBrandings', tenantId),
        fetchConfig('amfaPolicies', tenantId),
      ]);

      // Apply settings (non-policy fields)
      const { updatedAmfaConfigs, updatedAmfaLegals, updatedAmfaBrandings } = applySettingsToConfigs(
        incomingSettings,
        existingAmfaConfigs,
        existingAmfaLegals,
        existingAmfaBrandings
      );

      const savePromises = [
        saveConfig('amfaConfigs', tenantId, updatedAmfaConfigs),
        saveConfig('amfaLegals', tenantId, updatedAmfaLegals),
        saveConfig('amfaBrandings', tenantId, updatedAmfaBrandings),
      ];

      // Handle policies if provided
      let syncResults = null;
      if (incomingSettings.policies !== undefined) {
        const newPolicies = incomingSettings.policies;

        // Validate: special policy groups cannot be deleted
        const oldSpecial = Object.keys(existingPolicies || {}).filter(g => isSpecialPolicyGroup(g));
        const newKeys = Object.keys(newPolicies);
        const deletedSpecial = oldSpecial.filter(g => !newKeys.includes(g));
        if (deletedSpecial.length > 0) {
          return createResponse(400, {
            error: `Cannot delete special policy groups: ${deletedSpecial.join(', ')}`,
          });
        }

        // Sync Cognito groups (create/delete)
        syncResults = await syncCognitoGroups(existingPolicies, newPolicies, userPoolId);

        // If any group deletion failed because of users, return error
        const blockingErrors = syncResults.errors.filter(e => e.action === 'delete');
        if (blockingErrors.length > 0) {
          return createResponse(409, {
            error: 'Some groups could not be deleted',
            details: blockingErrors,
          });
        }

        savePromises.push(saveConfig('amfaPolicies', tenantId, newPolicies));
      }

      // Apply the Cognito password policy (skip the API call when nothing changed)
      let savedPasswordPolicy = undefined;
      if (cognitoPasswordPolicy) {
        const pool = await fetchUserPool(userPoolId);
        if (!samePasswordPolicy(cognitoPasswordPolicy, pool.Policies?.PasswordPolicy)) {
          await updatePasswordPolicy(pool, cognitoPasswordPolicy);
          logger.info(`Password policy updated for tenant ${tenantId}`);
        }
        savedPasswordPolicy = toUiPasswordPolicy(cognitoPasswordPolicy);
      }

      await Promise.all(savePromises);

      // Bump config version to invalidate service-side cache (near-real-time propagation)
      await bumpConfigVersion(tenantId);

      const settings = buildSettingsResponse(updatedAmfaConfigs, updatedAmfaLegals, updatedAmfaBrandings);
      const updatedPolicies = incomingSettings.policies !== undefined
        ? incomingSettings.policies
        : (existingPolicies || {});

      return createResponse(200, {
        data: {
          ...settings,
          policies: updatedPolicies,
          ...(savedPasswordPolicy && { password_policy: savedPasswordPolicy }),
        },
        ...(syncResults && { groupSync: syncResults }),
      });

    } else {
      return createResponse(405, { error: `Method ${httpMethod} not allowed` });
    }
  } catch (err) {
    logger.error('Settings Lambda error:', err);
    return createResponse(500, { type: 'exception', message: err.message || 'Internal server error' });
  }
};
